#!/usr/bin/env node
/**
 * scripts/check-generated-code.mjs
 *
 * Enforces the E1.2 generated-code policy:
 *
 *   1. Files under any `generated/`, `target/`, `dist/`, `build/`,
 *      `.next/` or `.gradle/` directory MUST be ignored by ESLint,
 *      Prettier, Spectral and the ownership walker.
 *   2. Files matching `*.generated.{ts,js,mjs,cjs,kt,java,go,rb,py}`
 *      must contain the marker `@generated` (or `// @generated` for
 *      Java) on the first line so humans never edit them.
 *   3. The marker must be in the first 5 lines of the file.
 *
 * If a file lacks the marker, CI fails — preventing accidental manual
 * edits that would be overwritten on the next codegen run.
 */
import { readdirSync, readFileSync, statSync, existsSync } from "node:fs";
import { join, relative, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = process.env.GENERATED_ROOT
  ? resolve(process.env.GENERATED_ROOT)
  : resolve(HERE, "..");

const IGNORE_DIRS = new Set([
  "node_modules",
  "dist",
  "build",
  ".next",
  ".gradle",
  ".turbo",
  "target",
  "coverage",
  "out",
  ".idea",
  ".vscode",
  "pnpm-lock.yaml",
  ".git",
]);

const GENERATED_PARENT_DIRS = new Set([
  "generated",
  "target",
  ".next",
  "build",
  "dist",
  "out",
]);

const GENERATED_FILE_PATTERNS = [
  /\.generated\.(ts|tsx|js|mjs|cjs|mts|cts|java|kt|kts|go|rb|py)$/i,
  /\.gen\.(ts|tsx|js|mjs|cjs|mts|cts|java|kt|kts|go|rb|py)$/i,
];

const MARKERS = [
  "@generated",
  "@GENERATED",
  "AUTOGENERATED",
  "Code generated",
  "DO NOT EDIT",
  "do not edit",
];

let violations = 0;
let scanned = 0;

function* walk(dir) {
  if (!existsSync(dir)) return;
  for (const entry of readdirSync(dir)) {
    if (IGNORE_DIRS.has(entry)) continue;
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) {
      yield* walk(full);
    } else {
      yield full;
    }
  }
}

function hasMarker(text) {
  const head = text.split(/\r?\n/).slice(0, 5).join("\n");
  return MARKERS.some((m) => head.includes(m));
}

for (const file of walk(ROOT)) {
  const rel = relative(ROOT, file);
  const parts = rel.split("/");
  const isInGeneratedDir = parts.some((p) => GENERATED_PARENT_DIRS.has(p));
  const isGeneratedName = GENERATED_FILE_PATTERNS.some((re) => re.test(rel));
  if (!isInGeneratedDir && !isGeneratedName) continue;

  scanned++;
  const text = readFileSync(file, "utf8");
  if (!hasMarker(text)) {
    violations++;
    console.error(
      `[generated] ${rel} — file is in a generated path but lacks '@generated' marker in first 5 lines`,
    );
  }
}

if (violations > 0) {
  console.error(
    `\n[generated] ${violations} violation(s); add the '@generated' marker to the first 5 lines of each generated file`,
  );
  process.exit(1);
}
console.log(
  `[generated] clean — ${scanned} generated file(s) carry the marker`,
);